/** 📸️ Joins current full bodies and explicit owned proposals without reconstructing retired test authorities. */
async function stage(){
 const driver=readFileSync(import.meta.filename,"utf8"),basePath=join(output,"current-origin-core-stage-13.json"),baseRaw=readFileSync(basePath,"utf8"),base=JSON.parse(baseRaw),cutsPath=join(input,"📥️next-source-admission-chain/📸️current-candidates-preimage-11.json"),cutsRaw=readFileSync(cutsPath,"utf8"),cuts=JSON.parse(cutsRaw).rows,rows=new Map<string,any>(base.rows.map((row:any)=>[row.path,{...row,origin:basePath}])),inputs:any[]=[{path:basePath,source:baseRaw,hash:sha(baseRaw)},{path:cutsPath,source:cutsRaw,hash:sha(cutsRaw)}];
 assert.equal(existsSync(authorityPath),false);assert.deepEqual(base.controls,controls);assert.equal(base.laws.length,41);assert.equal(readFileSync(base.driver.path,"utf8"),base.driver.source);
 for(const row of cuts){const origin=row.afterOrigin??join(input,"📥️next-source-admission-process",row.path);assert.equal(readFileSync(origin,"utf8"),row.after,"Current proposal advanced: "+row.path);const before=currentWholeRead(join(root,row.path));assert.equal(before?.toString("utf8")??null,row.source,"Current physical proposal advanced: "+row.path);rows.set(row.path,{path:row.path,before:row.source,beforeHash:row.source===null?null:sha(row.source),after:row.after,afterHash:sha(row.after),origin});inputs.push({path:origin,source:row.after,hash:sha(row.after)});}
