 const cargo="🧰️framework/🛍️products/🦑️repo/🔨️modules/📚️library/🗂️workspaces/🦀️cargo",unicode=cargo+"/📣️publication/🧪️tests/🔡️unicode-pages/🟦️.ts";for(const path of [cargo+"/📣️publication/🟦️.ts",cargo+"/📣️publication/🧬️schema/🔣️.json",unicode,dirname(unicode)+"/🧫️fixtures/🔣️.json"]){const origin=join(input,"📥️next-publication-unicode",path),after=readFileSync(origin,"utf8"),before=currentWholeRead(join(root,path))?.toString("utf8")??null;rows.set(path,{path,before,beforeHash:before===null?null:sha(before),after,afterHash:sha(after),origin});inputs.push({path:origin,source:after,hash:sha(after)});}
 const retirementPath=join(input,"📥️next-production-schema-projections/📸️fixed-corpus-authority-retirements-1.json"),retirementRaw=readFileSync(retirementPath,"utf8"),retirementDocument=JSON.parse(retirementRaw),retirements:any[]=[];inputs.push({path:retirementPath,source:retirementRaw,hash:sha(retirementRaw)});for(const row of Array.isArray(retirementDocument)?retirementDocument:retirementDocument.rows){const before=currentWholeRead(join(root,row.path))?.toString("utf8")??null;assert.equal(before,row.before??row.source??null,"Current retirement source advanced: "+row.path);retirements.push({path:row.path,before,beforeHash:before===null?null:sha(before),after:null,reason:row.reason});rows.delete(row.path);}
 for(const row of rows.values()){const before=currentWholeRead(join(root,row.path))?.toString("utf8")??null;assert.equal(before,row.before,"Unjoined current source advance: "+row.path);assert.equal(sha(row.after),row.afterHash);row.beforeHash=before===null?null:sha(before);delete row.entry;delete row.source;}
 const authority={schemaVersion:1,at:new Date().toISOString(),rows:[...rows.values()],retirements,inputs,laws:base.laws,callerPaths:[...new Set(base.callerFrames.map(row=>row.path))],controls,driver:{path:import.meta.filename,source:driver,hash:sha(driver)},sourceWrites:0,publicationReady:false},schemaPath=join(import.meta.dir,"🔣️authority.json"),schemaRaw=readFileSync(schemaPath,"utf8"),validate=new(require("ajv/dist/2020").default)({strict:true}).compile(JSON.parse(schemaRaw));assert.equal(validate(authority),true,JSON.stringify(validate.errors));assert.equal(validate({...authority,controls:{...controls,testLevel:"quick"}}),false);assert.equal(validate({...authority,retirements:[{...retirements[0],after:""}]}),false);assert.equal(validate({...authority,unknown:true}),false);for(const row of inputs)assert.equal(readFileSync(row.path,"utf8"),row.source);assert.equal(readFileSync(import.meta.filename,"utf8"),driver);assert.equal(readFileSync(schemaPath,"utf8"),schemaRaw);writeFileSync(authorityPath,JSON.stringify(authority));console.log("[DEBUG] "+JSON.stringify({phase:"current-source-stage",rows:rows.size,retirements:retirements.length,originalLaws:base.laws.length,sourceWrites:0}));
