/** 🧭️ Captures exact current static and literal runtime imports with mandatory absent-source refusal. */
async function inspect(){
 const raw=readFileSync(authorityPath,"utf8"),authority=JSON.parse(raw),driver=readFileSync(import.meta.filename,"utf8"),directory=join(output,"current-origin-inspect-"+epoch),snapshot=join(directory,"snapshot"),map=new Map<string,string>(authority.rows.map((row:any)=>[row.path,row.after])),retired=new Set<string>(authority.retirements.map((row:any)=>row.path)),entries=[...new Set<string>([...authority.laws,...map.keys()].filter(path=>path.endsWith(".ts")))],queue=[...entries],seen=new Set<string>(),frames:any[]=[],missing:any[]=[],journal=openSync(join((mkdirSync(directory,{recursive:true}),directory),"inputs.jsonl"),"wx");assert.equal(driver,authority.driver.source);
 try{while(queue.length){const path=queue.shift()!;if(seen.has(path))continue;seen.add(path);assert.ok(!path.startsWith("..")&&!isAbsolute(path));if(retired.has(path)){missing.push({path,reason:"Required source was explicitly retired"});continue;}const origin=join(root,path),source=map.get(path)??readFileSync(origin,"utf8"),destination=join(snapshot,path),frame={path,origin,source,hash:sha(source),candidate:map.has(path)};mkdirSync(dirname(destination),{recursive:true});writeFileSync(destination,source);frames.push(frame);writeSync(journal,JSON.stringify(frame)+"\n");if(path.endsWith(".mjs")||path.endsWith(".js")){const companion=path.endsWith(".mjs")?path.slice(0,-4)+".d.mts":path.slice(0,-3)+".d.ts";if(map.has(companion)||existsSync(join(root,companion)))queue.push(companion);}if(![".ts",".js",".mjs",".cjs"].some(ext=>path.endsWith(ext)))continue;const tree=ts.createSourceFile(path,source,ts.ScriptTarget.Latest,true);assert.equal(tree.parseDiagnostics.length,0,path);const add=(value:string,reference="module")=>{if(!value.startsWith("."))return;let target=relative(root,resolve(root,dirname(path),value));if(reference==="url"&&!map.has(target)&&existsSync(join(root,target))&&lstatSync(join(root,target)).isDirectory())return;if(!map.has(target)&&!existsSync(join(root,target))){if(map.has(target+".ts")||existsSync(join(root,target+".ts")))target+=".ts";else if(map.has(target+"/🟦️.ts")||existsSync(join(root,target+"/🟦️.ts")))target+="/🟦️.ts";}if(retired.has(target)||!map.has(target)&&!existsSync(join(root,target))){missing.push({from:path,path:target,reference,retired:retired.has(target)});return;}queue.push(target);};for(const node of tree.statements)if((ts.isImportDeclaration(node)||ts.isExportDeclaration(node))&&node.moduleSpecifier&&ts.isStringLiteral(node.moduleSpecifier))add(node.moduleSpecifier.text);const visit=(node:any)=>{if(ts.isCallExpression(node)&&node.arguments?.length===1&&ts.isStringLiteral(node.arguments[0])&&(node.expression.kind===ts.SyntaxKind.ImportKeyword||node.expression.getText(tree)==="require"||ts.isCallExpression(node.expression)&&node.expression.expression.getText(tree)==="createRequire"))add(node.arguments[0].text);if(ts.isImportTypeNode(node)&&ts.isLiteralTypeNode(node.argument)&&ts.isStringLiteral(node.argument.literal))add(node.argument.literal.text);if(ts.isNewExpression(node)&&node.expression.getText(tree)==="URL"&&node.arguments?.length===2&&ts.isStringLiteral(node.arguments[0])&&node.arguments[1].getText(tree)==="import.meta.url")add(node.arguments[0].text,"url");ts.forEachChild(node,visit);};visit(tree);}fsyncSync(journal);}finally{closeSync(journal);}
 const program=ts.createProgram(entries.map(path=>join(snapshot,path)),{noEmit:true,strict:true,skipLibCheck:true,target:ts.ScriptTarget.ESNext,module:ts.ModuleKind.ESNext,moduleResolution:ts.ModuleResolutionKind.Bundler,resolveJsonModule:true,allowImportingTsExtensions:true,types:["node","bun"]}),diagnostics=ts.getPreEmitDiagnostics(program).map((d:any)=>({path:d.file?relative(snapshot,d.file.fileName):null,line:d.file?d.file.getLineAndCharacterOfPosition(d.start??0).line+1:null,code:d.code,message:ts.flattenDiagnosticMessageText(d.messageText,"\n")})),posts=frames.map(frame=>({path:frame.path,snapshot:readFileSync(join(snapshot,frame.path),"utf8")===frame.source,physical:frame.candidate||readFileSync(frame.origin,"utf8")===frame.source}));writeFileSync(directory+".json",JSON.stringify({source:{path:authorityPath,hash:sha(raw)},laws:authority.laws,entries,frames,missing,diagnostics,posts,sourceWrites:0,publicationReady:false}));assert.equal(readFileSync(authorityPath,"utf8"),raw);assert.equal(readFileSync(import.meta.filename,"utf8"),driver);for(const row of authority.rows)assert.equal(currentWholeRead(join(root,row.path))?.toString("utf8")??null,row.before);assert.ok(posts.every(row=>row.snapshot&&row.physical));assert.deepEqual(missing,[]);assert.deepEqual(diagnostics,[]);console.log("[DEBUG] "+JSON.stringify({phase:"current-source-inspection",entries:entries.length,frames:frames.length,diagnostics:diagnostics.length}));
}

/** 🗃️ Selects only the active repository metadata roots from an explicit bounded policy. */
function metadataPath(path:string,policy:{required:readonly string[];optional:readonly string[]}):boolean{return path!==""&&!isAbsolute(path)&&!path.includes("\\")&&!path.split("/").some(part=>part===""||part==="."||part==="..")&&[...policy.required,...policy.optional].includes(path.split("/")[0]!);}
